import React, { useState } from "react";
import data from "../sentenceFormation.json";
import "animate.css";
import { useNavigate } from "react-router-dom";
import {
  Button,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Slider,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import useWebSocket, { ReadyState } from "react-use-websocket";
import { Modal } from "react-bootstrap";
import hint from "../images/hint2.png";

const Level2MidContent_copy = () => {
  const { t } = useTranslation();
  let navigate = useNavigate();
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomnoArray, setRandomNoArray] = useState([0]);
  let [isDisableNext, setIsDisableNext] = useState(true);
  let [skipCount, setSkipCount] = useState(0);
  let [level] = useState("Level 2");
  const [pageName] = useState("Level2");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [sentenceType, setSentenceType] = useState("");
  const sentArray = [
    ...data.level3.declarativeSentence,
    ...data.level3.exclamatorySentence,
    ...data.level3.imperativeSentence,
    ...data.level3.interrogativeSentence,
  ];
  const [showMessage, setShowMessage] = useState(false);
  const [answerStatus, setAnswerStatus] = useState("");
  const [showHint, setShowHint] = useState(false);

  const handleNext = () => {
    setIsDisableNext(true);
    setShowMessage(false);
    setAnswerStatus("");
    setSentenceType("");

    if (randomnoArray.length != 10) {
      let randomNo = Math.floor(Math.random() * data.level2.length);
      if (randomnoArray.includes(randomNo)) {
        handleNext();
      } else {
        setRandomNumber(randomNo);
        randomnoArray.push(randomNo);
      }
    } else {
      // Swal.fire({
      //   title: `You have successfully completed ${
      //     10 - skipCount
      //   } out of 10 sentences!`,
      //   showClass: {
      //     popup: "animate__animated animate__fadeInDown",
      //   },
      //   hideClass: {
      //     popup: "animate__animated animate__fadeOutUp",
      //   },
      //   customClass: {
      //     title: "completeion-text",
      //     htmlContainer: "completeion-text",
      //   },
      //   confirmButtonText: "Restart",
      // }).then((result) => {
      //   if (result.isConfirmed) {
      //     setRandomNoArray([0]);
      //     navigate("/");
      //   }
      // });

      setRandomNoArray([0]);
      navigate("/launchpage/englishactivity/level2/restart", {
        state: {
          levelName: "Types of sentences",
          levelToRestart: "Level 2",
          attempted: 10 - skipCount,
          totalCount: 10,
          type: "sentences",
        },
      });
    }

    ReactGA.event({
      action: `Eng15|Sentence formation|Clicked on next button of level 2`,
      category: `Eng15|next button click`,
      label: `Eng15|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "next",
      "Clicked",
      "navigate to next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
    ReactGA.event({
      action: `Eng15|Sentence formation|Clicked on level change dropdown`,
      category: `Eng15|next button click`,
      label: `Eng15|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "level change dropdown",
      "Clicked",
      "navigate to other level",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSentType = (event) => {
    setSentenceType(event.target.value);
    switch (event.target.value) {
      case "declarative":
        if (data.level3.declarativeSentence.includes(sentArray[randomNumber])) {
          setAnswerStatus("correct");
          setIsDisableNext(false);
        } else {
          setAnswerStatus("incorrect");
        }
        break;
      case "imperative":
        if (data.level3.imperativeSentence.includes(sentArray[randomNumber])) {
          setAnswerStatus("correct");
          setIsDisableNext(false);
        } else {
          setAnswerStatus("incorrect");
        }
        break;
      case "interrogative":
        if (
          data.level3.interrogativeSentence.includes(sentArray[randomNumber])
        ) {
          setAnswerStatus("correct");
          setIsDisableNext(false);
        } else {
          setAnswerStatus("incorrect");
        }
        break;
      case "exclamatory":
        if (data.level3.exclamatorySentence.includes(sentArray[randomNumber])) {
          setAnswerStatus("correct");
          setIsDisableNext(false);
        } else {
          setAnswerStatus("incorrect");
        }
        break;
      default:
        console.log("Invalid sentence type!");
        break;
    }
    setShowMessage(true);
  };

  const handleSkip = () => {
    let newCount = skipCount + 1;
    setSkipCount(newCount);
    handleNext();

    ReactGA.event({
      action: `Eng15|Sentence formation|Clicked on SKIP button`,
      category: `Eng15|SKIP button clicked`,
      label: `Eng15|Clicked on SKIP button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "SKIP",
      "Clicked",
      "Checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-5 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Types of sentences{" "}
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  label="Select Adverb"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>
              {sentenceType && answerStatus === "incorrect" && (
                <img
                  className="img-fluid ms-3"
                  src={hint}
                  alt="logo"
                  title={t("hint_tooltip")}
                  onClick={() => setShowHint(!showHint)}
                  style={{ cursor: "pointer" }}
                />
              )}
            </div>
          </div>

          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <span className="me-3">Sentence</span>

              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={10}
                value={randomnoArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",

                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomnoArray.length}/{10}
              </span>
            </div>
          </div>

          <div className="row mb-3">
            <div
              style={{
                background: "#EDF6FA",
                borderRadius: "10px",
                // boxShadow: "0px 3px 6px #00000029",
                paddingTop: "3%",
                paddingBottom: "3%",
              }}
            >
              <div className="ms-3 text-center">
                <b>Sentence</b>: {sentArray[randomNumber]}
              </div>
            </div>
          </div>

          <div className="row mb-3 justify-content-center">
            Select sentence type
          </div>

          <div className="row justify-content-center mb-3">
            <FormControl sx={{ width: "50%", background: "#F5B946" }}>
              <InputLabel id="demo-simple-select-label">
                Sentence type
              </InputLabel>
              <Select
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                value={sentenceType}
                label="Sentence type"
                onChange={handleSentType}
                sx={{ fontSize: "calc(.6rem + .4vw)" }}
              >
                <MenuItem value="declarative">Declarative sentence</MenuItem>
                <MenuItem value="imperative">Imperative sentence</MenuItem>
                <MenuItem value="interrogative">
                  Interrogative sentence
                </MenuItem>
                <MenuItem value="exclamatory">Exclamatory sentence</MenuItem>
              </Select>
            </FormControl>
          </div>

          <div className="row mb-3">
            <div className="d-flex justify-content-around">
              <Button
                variant="contained"
                onClick={handleSkip}
                sx={{ background: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
              >
                {t("skip")}
              </Button>

              <Button
                disabled={isDisableNext}
                variant="contained"
                onClick={handleNext}
                sx={{ background: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
              >
                {randomnoArray.length == 10 ? t("finish") : t("next")}
              </Button>
            </div>
          </div>

          <div className="row justify-content-center">
            {showMessage && (
              <div
                style={{
                  height: "auto",
                  width: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.5)",
                  padding: "1rem",
                  borderRadius: "50px",
                }}
              >
                {answerStatus === "correct" ? (
                  <div>
                    Correct! Current sentence is a type of{" "}
                    <span style={{ color: "#098B0D" }}>
                      {sentenceType}&nbsp;
                    </span>{" "}
                    sentence.
                  </div>
                ) : (
                  <div>
                    Incorrect! Current sentence is not a type of{" "}
                    <span style={{ color: "#BF4C4C" }}>
                      {sentenceType}&nbsp;
                    </span>
                    sentence.
                    <br />
                    See hint for reference.
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Hint Modal */}
          <Modal show={showHint} onHide={() => setShowHint(false)}>
            <Modal.Header
              closeButton
              style={{ background: "#90D5FF", fontSize: "calc(.6rem + .4vw)" }}
            >
              <Modal.Title>
                <b>{t("hint")}</b>
              </Modal.Title>
            </Modal.Header>
            <Modal.Body>
              <div style={{ fontSize: "calc(.6rem + .4vw)" }}>
                <ul>
                  <li>
                    <b>Definition: </b>
                    {sentenceType &&
                      data.feedback[sentenceType] &&
                      data.feedback[sentenceType].definition}
                  </li>
                  <li>
                    <b>Structure: </b>
                    {sentenceType &&
                      data.feedback[sentenceType] &&
                      data.feedback[sentenceType].structure}
                  </li>
                  <li>
                    {sentenceType &&
                      sentenceType.charAt(0).toUpperCase() +
                        sentenceType.slice(1)}{" "}
                    sentence always ends with{" "}
                    {sentenceType &&
                      data.feedback[sentenceType] &&
                      data.feedback[sentenceType].endsWith}
                  </li>
                </ul>
              </div>
            </Modal.Body>
            <Modal.Footer>
              <Button
                variant="contained"
                sx={{ fontSize: "calc(.6rem + .2vw)", background: "#0F477E" }}
                onClick={() => setShowHint(false)}
              >
                {t("close")}
              </Button>
            </Modal.Footer>
          </Modal>
          {/* Hint Modal */}
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <ul>
              {randomnoArray.length === 1 && (
                <>
                  <li>{t("instr5")}</li>
                  <li>{t("instr9")}</li>
                  <li>{t("instr6")}</li>
                </>
              )}

              {randomnoArray.length !== 1 && isDisableNext && (
                <>
                  <li>{t("instr9")}</li>
                  <li>{t("instr6")}</li>
                </>
              )}

              {isDisableNext ? (
                <li>{t("instr8")}</li>
              ) : randomnoArray.length === 10 ? (
                <li>{t("instr10")}</li>
              ) : (
                <li>{t("instr7")}</li>
              )}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2MidContent_copy;
